security = value['security']
canCreate = False
canEdit = False
canDelete = False
assignmentInfo = value['assignmentInfo']

if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['scheduleOperations']['enabled']:

		if assignmentInfo['startDate']:
			if (assignmentInfo['mode'] == 'crew' and assignmentInfo['crewId']): canCreate = True
			elif (assignmentInfo['mode'] == 'individual' and assignmentInfo['userId']): canCreate = True
		if len(value['selection']) > 0: canDelete = True
		if len(value['selection']) > 0 and value['selection'][0]['endDate'] is None:	canEdit = True

return {"canCreate": canCreate, "canDelete": canDelete, "canRead": True, "canUpdate": canEdit}
